The service owns the abstraction (`PaymentGateway`) and never imports a concrete provider; the composition root supplies the gateways and the routing table. Validation of the routing table happens once at construction, so a typo in configuration fails at startup instead of on the first EU payment.

**`payments.py`**

```python
from collections.abc import Mapping
from dataclasses import dataclass
from decimal import Decimal
from typing import Protocol


@dataclass(frozen=True)
class Charge:
    gateway: str
    amount: Decimal
    currency: str
    customer_id: str


class PaymentGateway(Protocol):
    def charge(self, amount: Decimal, currency: str, customer_id: str) -> Charge: ...


class ConfigurationError(Exception):
    """The routing table references a gateway that was not provided."""


class CheckoutService:
    def __init__(
        self,
        gateways: Mapping[str, PaymentGateway],
        routes: Mapping[str, str],
        default: str,
    ) -> None:
        self._gateways = dict(gateways)
        self._routes = {country.upper(): name for country, name in routes.items()}
        self._default = default
        unknown = ({default} | set(self._routes.values())) - self._gateways.keys()
        if unknown:
            raise ConfigurationError(f"unknown gateways: {sorted(unknown)}")

    def gateway_for(self, country: str) -> str:
        return self._routes.get(country.upper(), self._default)

    def checkout(self, country: str, amount: Decimal, currency: str, customer_id: str) -> Charge:
        if amount <= 0:
            raise ValueError("amount must be positive")
        gateway = self._gateways[self.gateway_for(country)]
        return gateway.charge(amount, currency, customer_id)
```

**`test_payments.py`**

```python
from decimal import Decimal

import pytest

from payments import Charge, CheckoutService, ConfigurationError


class FakeGateway:
    def __init__(self, name: str) -> None:
        self.name = name
        self.calls: list[tuple[Decimal, str, str]] = []

    def charge(self, amount: Decimal, currency: str, customer_id: str) -> Charge:
        self.calls.append((amount, currency, customer_id))
        return Charge(self.name, amount, currency, customer_id)


def make_service() -> tuple[CheckoutService, FakeGateway, FakeGateway]:
    razorpay, stripe = FakeGateway("razorpay"), FakeGateway("stripe")
    service = CheckoutService(
        gateways={"razorpay": razorpay, "stripe": stripe},
        routes={"IN": "razorpay", "DE": "stripe", "FR": "stripe"},
        default="stripe",
    )
    return service, razorpay, stripe


def test_routes_by_country() -> None:
    service, razorpay, stripe = make_service()
    assert service.checkout("IN", Decimal("10"), "INR", "c1").gateway == "razorpay"
    assert service.checkout("DE", Decimal("10"), "EUR", "c2").gateway == "stripe"
    assert len(razorpay.calls) == 1 and len(stripe.calls) == 1


def test_unknown_country_uses_default_and_is_case_insensitive() -> None:
    service, _, _ = make_service()
    assert service.gateway_for("br") == "stripe"
    assert service.gateway_for("in") == "razorpay"


def test_rejects_non_positive_amount_without_calling_gateway() -> None:
    service, razorpay, _ = make_service()
    with pytest.raises(ValueError):
        service.checkout("IN", Decimal("0"), "INR", "c1")
    assert razorpay.calls == []


def test_unknown_gateway_in_config_fails_fast() -> None:
    with pytest.raises(ConfigurationError):
        CheckoutService({"stripe": FakeGateway("stripe")}, {"IN": "razorpay"}, default="stripe")
    with pytest.raises(ConfigurationError):
        CheckoutService({"stripe": FakeGateway("stripe")}, {}, default="paypal")


def test_new_gateway_needs_no_change_to_service() -> None:
    class AdyenGateway:
        def charge(self, amount: Decimal, currency: str, customer_id: str) -> Charge:
            return Charge("adyen", amount, currency, customer_id)

    service = CheckoutService({"adyen": AdyenGateway()}, {"NL": "adyen"}, default="adyen")
    assert service.checkout("NL", Decimal("5"), "EUR", "c9").gateway == "adyen"


def test_caller_mutating_inputs_after_construction_has_no_effect() -> None:
    razorpay, stripe = FakeGateway("razorpay"), FakeGateway("stripe")
    gateways = {"razorpay": razorpay, "stripe": stripe}
    routes = {"IN": "razorpay"}
    service = CheckoutService(gateways, routes, default="stripe")
    routes["IN"] = "stripe"
    gateways.clear()
    assert service.checkout("IN", Decimal("1"), "INR", "c1").gateway == "razorpay"
```

Run the tests with `pytest -q`.

`FallbackChat` is a composite: it satisfies the same Protocol as the models it wraps, which is what LSP asks for. Narrow exception handling is the key design choice, because swallowing a `ValueError` from a buggy adapter would hide defects and silently route traffic to a more expensive model. The contract checker is plain data in, strings out, so it can be reused as a parametrised test for every provider adapter.

**`chat.py`**

```python
from collections.abc import Sequence
from dataclasses import dataclass
from typing import Protocol


@dataclass(frozen=True)
class Completion:
    text: str
    input_tokens: int = 0
    output_tokens: int = 0


class ProviderError(Exception):
    """Transient provider failure: timeout, 5xx, rate limit."""


class ChatModel(Protocol):
    def complete(self, prompt: str, *, max_tokens: int = 512) -> Completion: ...


class FallbackChat:
    """Try each model in order; only ProviderError triggers the next one."""

    def __init__(self, models: Sequence[ChatModel]) -> None:
        if not models:
            raise ValueError("at least one model is required")
        self._models = tuple(models)

    def complete(self, prompt: str, *, max_tokens: int = 512) -> Completion:
        errors: list[Exception] = []
        for model in self._models:
            try:
                return model.complete(prompt, max_tokens=max_tokens)
            except ProviderError as exc:
                errors.append(exc)
        raise ExceptionGroup("all providers failed", errors)


def contract_violations(model: ChatModel) -> list[str]:
    """Return human-readable contract violations; an empty list means compliant.

    Contract: complete() accepts the default and any max_tokens in 1..4096,
    returns a Completion whose text is a str, and may raise only ProviderError.
    """
    problems: list[str] = []
    for label, kwargs in (("default", {}), ("max_tokens=1", {"max_tokens": 1}),
                          ("max_tokens=4096", {"max_tokens": 4096})):
        try:
            result = model.complete("ping", **kwargs)
        except ProviderError:
            continue
        except Exception as exc:
            problems.append(f"{label}: raised {type(exc).__name__}")
            continue
        if not isinstance(result, Completion) or not isinstance(result.text, str):
            problems.append(f"{label}: did not return a Completion with str text")
    return problems
```

**`test_chat.py`**

```python
import pytest

from chat import Completion, FallbackChat, ProviderError, contract_violations


class EchoModel:
    def __init__(self) -> None:
        self.calls = 0

    def complete(self, prompt: str, *, max_tokens: int = 512) -> Completion:
        self.calls += 1
        return Completion(prompt[:max_tokens])


class DownModel:
    def __init__(self) -> None:
        self.calls = 0

    def complete(self, prompt: str, *, max_tokens: int = 512) -> Completion:
        self.calls += 1
        raise ProviderError("503")


class BuggyModel:
    def complete(self, prompt: str, *, max_tokens: int = 512) -> Completion:
        raise ValueError("bug in adapter")


class CappedModel:
    def complete(self, prompt: str, *, max_tokens: int = 512) -> Completion:
        if max_tokens > 256:
            raise ValueError("max_tokens must be <= 256")
        return Completion(prompt[:max_tokens])


def test_first_success_wins_and_later_models_are_not_called() -> None:
    first, second = EchoModel(), EchoModel()
    assert FallbackChat([first, second]).complete("hello").text == "hello"
    assert (first.calls, second.calls) == (1, 0)


def test_falls_back_on_provider_error() -> None:
    down, echo = DownModel(), EchoModel()
    assert FallbackChat([down, echo]).complete("hi").text == "hi"
    assert (down.calls, echo.calls) == (1, 1)


def test_all_failing_raises_exception_group_with_every_cause() -> None:
    with pytest.raises(ExceptionGroup) as info:
        FallbackChat([DownModel(), DownModel()]).complete("hi")
    assert len(info.value.exceptions) == 2


def test_programming_errors_are_not_swallowed() -> None:
    echo = EchoModel()
    with pytest.raises(ValueError):
        FallbackChat([BuggyModel(), echo]).complete("hi")
    assert echo.calls == 0


def test_empty_model_list_is_rejected() -> None:
    with pytest.raises(ValueError):
        FallbackChat([])


def test_contract_accepts_compliant_model() -> None:
    assert contract_violations(EchoModel()) == []
    assert contract_violations(DownModel()) == []


def test_contract_flags_strengthened_precondition() -> None:
    problems = contract_violations(CappedModel())
    assert any("default" in p for p in problems)
    assert any("max_tokens=4096" in p for p in problems)
    assert not any("max_tokens=1:" in p for p in problems)


def test_composite_is_itself_substitutable() -> None:
    assert contract_violations(FallbackChat([DownModel(), EchoModel()])) == []
```

Run the tests with `pytest -q`.
